import React, { useMemo, useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { GALLERY } from "./Content";

const TABS = ["All", "Weddings", "Corporate", "Parties", "Festivals"];

// Tab button variants
const tabVariants = {
  initial: { scale: 1 },
  active: { scale: 1.05 },
  hover: { scale: 1.08 }
};

// Image card variants
const cardVariants = {
  hidden: { opacity: 0, y: 30, scale: 0.95 },
  visible: (i) => ({
    opacity: 1,
    y: 0,
    scale: 1,
    transition: {
      delay: i * 0.05,
      duration: 0.5,
      ease: [0.25, 0.46, 0.45, 0.94]
    }
  }),
  hover: {
    scale: 1.03,
    transition: { duration: 0.3 }
  }
};

// Image zoom on hover
const imageVariants = {
  hover: { scale: 1.15, transition: { duration: 0.8, ease: "easeOut" } }
};

// Caption slide up
const captionVariants = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0, transition: { delay: 0.1, duration: 0.3 } }
};

export default function Portfolio() {
  const [active, setActive] = useState("All");
  const items = useMemo(() => active === "All" ? GALLERY : GALLERY.filter((g) => g.category === active), [active]);

  return (
    <section id="portfolio" className="relative px-6 md:px-12 lg:px-24 py-24 md:py-32" style={{ background: "#ffffff" }}>
      <div className="flex items-end justify-between flex-wrap gap-6 mb-12">
        <motion.div
          initial={{ opacity: 0, x: -30 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
        >
          <div className="overline mb-4">Our Work</div>
          <h2 className="serif" style={{ fontSize: "clamp(36px, 5vw, 72px)", lineHeight: 1.02, fontWeight: 400, color: "#1a080a", maxWidth: 720 }}>
            Selected <span style={{ color: "#d4af37", fontStyle: "italic" }}>moments</span> we've adorned.
          </h2>
        </motion.div>

        <motion.div
          className="flex flex-wrap gap-2"
          initial={{ opacity: 0, x: 30 }}
          whileInView={{ opacity: 1, x: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6, delay: 0.1 }}
        >
          {TABS.map((t) => (
            <motion.button
              key={t}
              onClick={() => setActive(t)}
              className="px-5 py-2 rounded-full text-xs tracking-[0.18em] uppercase transition-all duration-300"
              style={{
                background: active === t ? "linear-gradient(135deg,#d4af37,#f4d77a)" : "transparent",
                color: active === t ? "#1a080a" : "rgba(26,8,10,0.7)",
                border: active === t ? "none" : "1px solid rgba(212,175,55,0.4)",
                fontWeight: 600
              }}
              variants={tabVariants}
              animate={active === t ? "active" : "initial"}
              whileHover="hover"
            >
              {t}
            </motion.button>
          ))}
        </motion.div>
      </div>

      <motion.div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 auto-rows-[220px] gap-4">
        <AnimatePresence mode="popLayout">
          {items.map((it, i) => (
            <motion.figure
              key={`${active}-${it.src}`}
              className={`group relative overflow-hidden rounded-lg ${i % 5 === 0 ? "row-span-2" : ""}`}
              style={{ border: "1px solid rgba(212,175,55,0.3)", cursor: "pointer" }}
              custom={i}
              variants={cardVariants}
              initial="hidden"
              animate="visible"
              exit={{ opacity: 0, scale: 0.8, transition: { duration: 0.2 } }}
              whileHover="hover"
              layout
            >
              {/* Image with zoom */}
              <motion.img
                src={it.src}
                alt={it.title}
                loading="lazy"
                className="absolute inset-0 w-full h-full object-cover"
                variants={imageVariants}
              />

              {/* Gradient overlay */}
              <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(0,0,0,0) 40%, rgba(0,0,0,0.8) 100%)" }} />

              {/* Caption */}
              <motion.figcaption
                className="absolute bottom-3 left-4 right-4"
                variants={captionVariants}
                initial="hidden"
                animate="visible"
              >
                <div className="text-xs font-semibold tracking-wider uppercase mb-1" style={{ color: "#d4af37" }}>{it.category}</div>
                <div className="serif text-lg" style={{ color: "#ffffff", fontWeight: 400 }}>{it.title}</div>
              </motion.figcaption>

              {/* Hover overlay */}
              <motion.div
                className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none"
                style={{ background: "linear-gradient(180deg, transparent 0%, rgba(212,175,55,0.2) 100%)" }}
              />
            </motion.figure>
          ))}
        </AnimatePresence>
      </motion.div>
    </section>
  );
}
